mapper.select:
SELECT si.supplier_id AS supplierId, si.supplier_name AS supplierName, DATE_FORMAT(si.stock_in_time, '%Y-%m') AS period, COUNT(DISTINCT si.id) AS inCount, SUM(sid.actual_qty) AS totalQty, SUM(sid.total_amount) AS totalAmount FROM mis_stock_in si INNER JOIN mis_stock_in_detail sid ON si.id = sid.stock_in_id AND sid.del_flag = '0' WHERE si.status = 'FINISHED' AND si.del_flag = '0' AND si.stock_in_time IS NOT NULL
AND DATE_FORMAT(si.stock_in_time, '%Y-%m') >= #{startPeriod}
AND DATE_FORMAT(si.stock_in_time, '%Y-%m') <= #{endPeriod}
AND si.supplier_id = #{supplierId}
GROUP BY si.supplier_id, DATE_FORMAT(si.stock_in_time, '%Y-%m') ORDER BY period DESC, totalAmount DESC

SELECT si.supplier_id AS supplierId, si.supplier_name AS supplierName, DATE_FORMAT(si.stock_in_time, '%Y-%m') AS period, COUNT(DISTINCT si.id) AS inCount, SUM(sid.actual_qty) AS totalQty, SUM(sid.total_amount) AS totalAmount FROM mis_stock_in si INNER JOIN mis_stock_in_detail sid ON si.id = sid.stock_in_id AND sid.del_flag = '0' WHERE si.status = 'FINISHED' AND si.del_flag = '0' AND si.stock_in_time IS NOT NULL
AND DATE_FORMAT(si.stock_in_time, '%Y-%m') >= #{startPeriod}
AND DATE_FORMAT(si.stock_in_time, '%Y-%m') <= #{endPeriod}
AND si.supplier_id = #{supplierId}
GROUP BY si.supplier_id, DATE_FORMAT(si.stock_in_time, '%Y-%m') ORDER BY period DESC, totalAmount DESC

SELECT so.customer_id AS customerId, so.customer_name AS customerName, DATE_FORMAT(so.stock_out_time, '%Y-%m') AS period, COUNT(DISTINCT so.id) AS outCount, SUM(sod.actual_qty) AS totalQty, SUM(sod.sales_total) AS totalSalesAmount, SUM(sod.cost_total) AS totalCostAmount FROM mis_stock_out so INNER JOIN mis_stock_out_detail sod ON so.id = sod.stock_out_id AND sod.del_flag = '0' WHERE so.status = 'FINISHED' AND so.del_flag = '0' AND so.stock_out_time IS NOT NULL
AND DATE_FORMAT(so.stock_out_time, '%Y-%m') >= #{startPeriod}
AND DATE_FORMAT(so.stock_out_time, '%Y-%m') <= #{endPeriod}
AND so.customer_id = #{customerId}
GROUP BY so.customer_id, DATE_FORMAT(so.stock_out_time, '%Y-%m') ORDER BY period DESC, totalSalesAmount DESC

